tring? // e.g. \"Impact\", \"ShareASale\", \"Rakuten\", \"Direct\"\n  subIdParamName   String? // e.g. \"subId1\" or \"u1\"\n  commissionRate   Decimal? @db.Decimal(5, 2)\n  isActive         Boolean  @default(true)\n\n  products  Product[]\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n}\n\nmodel Product {\n  id          String   @id @default(uuid())\n  merchantId  String\n  merchant    Merchant @relation(fields: [merchantId], references: [id], onDelete: Restrict)\n  externalId  String // Merchant's SKU or Product ID\n  title       String\n  brand       String\n  description String?\n\n  category         ClothingCategory\n  subCategory      String\n  displayCategory  String?\n  styleCategory    String? // e.g. \"Casual\", \"Party\", \"Traditional\", \"Ethnic\", \"Formal\", \"Office\", \"Wedding\", \"Festive\", \"Streetwear\", \"Sportswear\"\n  primaryColorHex  String\n  primaryColorName String\n  pattern          String           @default(\"Solid\")\n  formalityLevel   Formality        @default(SMART_CASUAL)\n  seasons          String[]\n\n  price       Decimal  @db.Decimal(10, 2)\n  currency    String   @default(\"INR\")\n  retailPrice Decimal? @db.Decimal(10, 2)\n  inStock     Boolean  @default(false)\n\n  productUrl               String // Base landing page\n  affiliateUrl             String? // Pre-computed or template redirect\n  imageUrls                String[] // High-res product images\n  availableSizes           String[]                  @default([])\n  imageAttributionUrl      String?\n  imagePermissionConfirmed Boolean                   @default(false)\n  dataSource               ProductDataSource         @default(ADMIN_MANUAL)\n  verificationStatus       ProductVerificationStatus @default(UNVERIFIED)\n  verifiedAt               DateTime?\n  sourceReference          String?\n  lastPriceVerified        DateTime?                 @default(now())\n\n  outfitItems   OutfitItem[]\n  wishlistItems WishlistItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([merchantId, externalId])\n  @@index([category, price])\n  @@index([styleCategory])\n  @@index([brand])\n  @@index([primaryColorName])\n  @@index([verificationStatus, inStock])\n  @@index([dataSource])\n}\n\nmodel Outfit {\n  id     String @id @default(uuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  name            String\n  occasion        String // e.g. \"Work Presentation\", \"Weekend Brunch\"\n  season          String?\n  targetFormality Formality @default(CASUAL)\n\n  // Deterministic Scoring Breakdown\n  overallScore      Float // 0 - 100\n  colorHarmonyScore Float // 0 - 100\n  silhouetteScore   Float // 0 - 100\n  formalityScore    Float // 0 - 100\n  ruleBreakdown     Json // Explainability payload for audit and UI\n\n  // Natural-language styling advice returned by the configured provider\n  stylingAdvice String? @db.Text\n\n  isCurated     Boolean @default(false)\n  isUserCreated Boolean @default(false)\n\n  items              OutfitItem[]\n  savedOutfits       SavedOutfit[]\n  recommendationLogs RecommendationLog[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId, overallScore])\n}\n\nmodel OutfitItem {\n  id       String @id @default(uuid())\n  outfitId String\n  outfit   Outfit @relation(fields: [outfitId], references: [id], onDelete: Cascade)\n\n  wardrobeItemId String?\n  wardrobeItem   WardrobeItem? @relation(fields: [wardrobeItemId], references: [id], onDelete: SetNull)\n\n  productId String?\n  product   Product? @relation(fields: [productId], references: [id], onDelete: SetNull)\n\n  slotType   ClothingCategory\n  layerOrder Int              @default(1) // 1: base layer, 2: mid layer, 3: outerwear\n\n  @@index([outfitId])\n  @@index([wardrobeItemId])\n  @@index([productId])\n}\n\nmodel SavedOutfit {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  outfitId  String\n  outfit    Outfit   @relation(fields: [outfitId], references: [id], onDelete: Cascade)\n  notes     String?\n  createdAt DateTime @default(now())\n\n  @@unique([userId, outfitId])\n}\n\nmodel WishlistItem {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  createdAt DateTime @default(now())\n\n  @@unique([userId, productId])\n}\n\nmodel RecommendationLog {\n  id       String @id @default(uuid())\n  userId   String\n  user     User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  outfitId String\n  outfit   Outfit @relation(fields: [outfitId], references: [id], onDelete: Cascade)\n\n  context      Json // Occasion, weather, budget constraint requested\n  userRating   Int? // 1 (Dislike) to 5 (Love)\n  feedbackTags String[] // [\"too_formal\", \"clashing_colors\", \"too_expensive\"]\n  feedbackText String?\n\n  createdAt DateTime @default(now())\n\n  @@index([userId, createdAt])\n}\n\nmodel AuditLog {\n  id        String   @id @default(uuid())\n  userId    String?\n  user      User?    @relation(fields: [userId], references: [id], onDelete: SetNull)\n  action    String // e.g. \"USER_REGISTERED\", \"DATA_DELETION_REQUESTED\", \"PROFILE_PURGED\"\n  ipAddress String?\n  userAgent String?\n  details   Json?\n  createdAt DateTime @default(now())\n\n  @@index([action, createdAt])\n}\n",
  "inlineSchemaHash": "a3f7315a09d095d2df29cf475e4e2022322841f8c349e4830ef42fb2c596e3a1",
